CREATE TABLE ca_transitions (
    id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL,
    version BIGINT NOT NULL,
    source_authority_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    target_authority_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    mode VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    state VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    reported_by VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    reported_at BIGINT NOT NULL,
    reason LONGTEXT NOT NULL,
    PRIMARY KEY (id),
    CHECK (mode IN ('normal','emergency')),
    CHECK (state IN ('in_progress','externally_completed','closed')),
    CHECK (target_authority_id IS NULL OR target_authority_id <> source_authority_id),
    CHECK (length(id) = 36),
    CHECK (version >= 0),
    CHECK (length(source_authority_id) = 36),
    CHECK (length(target_authority_id) = 36),
    CHECK (length(mode) <= 32),
    CHECK (length(state) <= 32),
    CHECK (length(reported_by) = 36)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;

CREATE TABLE transition_impacts (
    transition_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    certificate_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    replacement_certificate_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    reissued_at BIGINT,
    PRIMARY KEY (transition_id, certificate_id),
    CHECK (length(transition_id) = 36),
    CHECK (length(certificate_id) = 36),
    CHECK (length(replacement_certificate_id) = 36)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;

CREATE TABLE deployment_confirmations (
    id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    created_at BIGINT NOT NULL,
    transition_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    certificate_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    target_label LONGTEXT NOT NULL,
    action VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    confirmed_by VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    confirmed_at BIGINT,
    PRIMARY KEY (id),
    CHECK (action IN ('trust_added','certificate_installed','trust_removed')),
    CHECK (length(id) = 36),
    CHECK (length(transition_id) = 36),
    CHECK (length(certificate_id) = 36),
    CHECK (length(action) <= 32),
    CHECK (length(confirmed_by) = 36)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;

CREATE TABLE tls_versions (
    id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    created_at BIGINT NOT NULL,
    source VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    key_material_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    managed_certificate_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    leaf_der LONGBLOB NOT NULL,
    chain_bundle LONGBLOB NOT NULL,
    validated_service_url LONGTEXT,
    not_after BIGINT NOT NULL,
    PRIMARY KEY (id),
    CHECK (source IN ('bootstrap','managed','external')),
    CHECK (source = 'bootstrap' OR validated_service_url IS NOT NULL),
    CHECK (length(id) = 36),
    CHECK (length(source) <= 32),
    CHECK (length(key_material_id) = 36),
    CHECK (length(managed_certificate_id) = 36)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;

CREATE TABLE tls_changes (
    id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    created_at BIGINT NOT NULL,
