    CHECK (length(candidate_version_id) = 36),
    CHECK (length(phase) <= 32),
    CHECK (length(error_code) <= 64)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;

CREATE TABLE maintenance_runs (
    id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL,
    version BIGINT NOT NULL,
    kind VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    phase VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    details_json LONGTEXT NOT NULL,
    started_at BIGINT NOT NULL,
    completed_at BIGINT,
    error_code VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin,
    PRIMARY KEY (id),
    CHECK (length(id) = 36),
    CHECK (version >= 0),
    CHECK (length(kind) <= 32),
    CHECK (length(phase) <= 32),
    CHECK (length(error_code) <= 64)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;

CREATE TABLE maintenance_crl_requirements (
    maintenance_run_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    ca_key_generation_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    minimum_generation BIGINT NOT NULL,
    minimum_number_hex VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    satisfied_crl_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    PRIMARY KEY (maintenance_run_id, ca_key_generation_id),
    CHECK (length(maintenance_run_id) = 36),
    CHECK (length(ca_key_generation_id) = 36),
    CHECK (minimum_generation >= 0),
    CHECK (length(minimum_number_hex) BETWEEN 1 AND 40),
    CHECK ((length(minimum_number_hex) = 1 OR substr(minimum_number_hex,1,1) <> '0')),
    CHECK (minimum_number_hex REGEXP '^[0-9a-f]+$'),
    CHECK (length(satisfied_crl_id) = 36)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;

CREATE TABLE jobs (
    id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL,
    version BIGINT NOT NULL,
    kind VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    dedup_key VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    payload_version BIGINT NOT NULL,
    payload_json LONGTEXT NOT NULL,
    state VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    available_at BIGINT NOT NULL,
    lease_until BIGINT,
    attempt_count BIGINT NOT NULL,
    last_error_code VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin,
    PRIMARY KEY (id),
    UNIQUE (dedup_key),
    CHECK (state IN ('pending','running','succeeded','failed')),
    CHECK (length(id) = 36),
    CHECK (version >= 0),
    CHECK (length(kind) <= 32),
    CHECK (length(dedup_key) <= 128),
    CHECK (payload_version >= 0),
    CHECK (length(state) <= 32),
    CHECK (attempt_count >= 0),
    CHECK (length(last_error_code) <= 64)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
